@app.route('/api/trampoline/calibration/<analysis_id>', methods=['GET', 'POST'])
def trampoline_calibration(analysis_id: str):
    """Persist or fetch bed calibration for one analysis directory."""

    analysis_dir = resolve_analysis_dir(get_trampoline_artifacts_dir(), analysis_id)
    if not analysis_dir.is_dir():
        return jsonify({'success': False, 'error': 'Analysis directory not found'}), 404

    if request.method == 'GET':
        calibration = load_calibration(analysis_dir)
        return jsonify(
            {
                'success': True,
                'analysis_id': analysis_id,
                'calibration': calibration.model_dump(mode="json") if calibration else None,
            }
        )

    payload = request.get_json(silent=True) or {}
    corners = payload.get("corners")
    if not isinstance(corners, dict):
        return jsonify({'success': False, 'error': 'corners must be provided'}), 400

    frames_meta = load_analysis_output(analysis_dir)["frames_meta"]
    calibration = create_bed_calibration(
        corners=corners,
        frame_width=int(frames_meta["width"]),
        frame_height=int(frames_meta["height"]),
    )
    save_calibration(calibration, analysis_dir)
    segmentation_payload = None
    try:
        segmentation_payload = segment_analysis_dir(analysis_dir)
    except FileNotFoundError:
        segmentation_payload = None

    with trampoline_analyses_lock:
        job = trampoline_analyses.setdefault(analysis_id, {})
        job["result"] = load_analysis_output(analysis_dir)

    return jsonify(
        {
            'success': True,
            'analysis_id': analysis_id,
            'calibration': calibration.model_dump(mode="json"),
            'segmentation': segmentation_payload,
        }
    )


@app.route('/api/trampoline/segment/<analysis_id>', methods=['POST'])
def trampoline_segment_analysis(analysis_id: str):
    """Generate automatic jump segmentation for one analysis directory."""

    analysis_dir = resolve_analysis_dir(get_trampoline_artifacts_dir(), analysis_id)
    if not analysis_dir.is_dir():
        return jsonify({'success': False, 'error': 'Analysis directory not found'}), 404

    try:
        segmentation = segment_analysis_dir(analysis_dir)
        result = load_analysis_output(analysis_dir)
    except Exception as exc:
        return jsonify({'success': False, 'error': str(exc)}), 400

    return jsonify(
        {
            'success': True,
            'analysis_id': analysis_id,
            'segmentation': segmentation,
            'result': result,
        }
    )


@app.route('/api/trampoline/overrides/<analysis_id>', methods=['GET', 'POST'])
def trampoline_timeline_overrides(analysis_id: str):
    """Fetch or persist manual jump timeline overrides."""

    analysis_dir = resolve_analysis_dir(get_trampoline_artifacts_dir(), analysis_id)
    if not analysis_dir.is_dir():
        return jsonify({'success': False, 'error': 'Analysis directory not found'}), 404

    if request.method == 'GET':
        timeline = _load_timeline_payload(analysis_dir)
        return jsonify({'success': True, 'analysis_id': analysis_id, **timeline})

    payload = request.get_json(silent=True) or {}
    jump_rows = payload.get("jump_segments")
    if not isinstance(jump_rows, list):
        return jsonify({'success': False, 'error': 'jump_segments must be provided'}), 400

    try:
        jump_segments = [JumpSegment.model_validate(item) for item in jump_rows]
        overrides = persist_timeline_overrides(analysis_dir, jump_segments)
        result = load_analysis_output(analysis_dir)
    except Exception as exc:
        return jsonify({'success': False, 'error': str(exc)}), 400

    with trampoline_analyses_lock:
        job = trampoline_analyses.setdefault(analysis_id, {})
        job["result"] = result

    return jsonify(
        {
            'success': True,
            'analysis_id': analysis_id,
            'overrides': overrides.model_dump(mode="json"),
            'result': result,
        }
    )


@app.route('/api/trampoline/labels/<analysis_id>', methods=['POST'])
def trampoline_label_overrides(analysis_id: str):
    """Persist one manual label override for the selected jump."""

    analysis_dir = resolve_analysis_dir(get_trampoline_artifacts_dir(), analysis_id)
    if not analysis_dir.is_dir():
        return jsonify({'success': False, 'error': 'Analysis directory not found'}), 404

    payload = request.get_json(silent=True) or {}
    jump_id = payload.get("jump_id")
    override_label = payload.get("override_label")
    override_note = payload.get("override_note")
    if not isinstance(jump_id, str) or not jump_id.strip():
        return jsonify({'success': False, 'error': 'jump_id is required'}), 400
    if override_label not in {None, "tuck", "pike", "straight"}:
        return jsonify({'success': False, 'error': 'override_label must be tuck, pike, straight, or null'}), 400
    if override_note is not None and not isinstance(override_note, str):
        return jsonify({'success': False, 'error': 'override_note must be a string when provided'}), 400

    try:
        labels = persist_label_override(
            analysis_dir,
            jump_id=jump_id.strip(),
            override_label=override_label,
            override_note=(override_note or "").strip() or None,
        )
        result = load_analysis_output(analysis_dir)
    except Exception as exc:
        return jsonify({'success': False, 'error': str(exc)}), 400

    with trampoline_analyses_lock:
        job = trampoline_analyses.setdefault(analysis_id, {})
        job["result"] = result

    return jsonify(
        {
            'success': True,
            'analysis_id': analysis_id,
            'labels': labels.model_dump(mode="json"),
            'result': result,
        }
    )


@app.route('/api/trampoline/video/<analysis_id>')
def trampoline_source_video(analysis_id: str):
    """Serve the source video for one analysis."""

    payload = _build_trampoline_status_payload(analysis_id)
    source_video = payload.get("source_video")
    if not source_video:
        return jsonify({'success': False, 'error': 'Video not found'}), 404
    video_path = resolve_repo_path(source_video)
    if not video_path.is_file():
        video_path = Path(source_video)
    if not video_path.is_file():
        return jsonify({'success': False, 'error': 'Video not found'}), 404
    return send_file(video_path, mimetype="video/mp4")

@app.route('/api/video/upload', methods=['POST'])
def upload_video():
    """Upload video for analysis"""
    if 'video' not in request.files:
        return jsonify({'success': False, 'error': 'No video file provided'})

    video_file = request.files['video']
    exercise_type = request.form.get('exercise_type')

    if not exercise_type:
        return jsonify({'success': False, 'error': 'No exercise type specified'})

    if video_file.filename == '':
        return jsonify({'success': False, 'error': 'No file selected'})

    # Check file size (in memory before saving)
    video_file.seek(0, 2)  # Seek to end
    file_size = video_file.tell()
    video_file.seek(0)  # Seek back to start

    max_size_bytes = MAX_VIDEO_SIZE_MB * 1024 * 1024
    if file_size > max_size_bytes:
        return jsonify({
            'success': False, 
            'error': f'Video çok büyük! Max {MAX_VIDEO_SIZE_MB}MB, yüklenen: {file_size / (1024*1024):.1f}MB'
        })

    # Generate unique ID
    video_id = str(uuid.uuid4())

    # Save video
    filename = f"{video_id}_{video_file.filename}"
    filepath = os.path.join(UPLOAD_FOLDER, filename)
    video_file.save(filepath)

    # Check video duration
    cap = cv2.VideoCapture(filepath)
    if cap.isOpened():
        fps = cap.get(cv2.CAP_PROP_FPS) or 30
        frame_count = cap.get(cv2.CAP_PROP_FRAME_COUNT)
        duration = frame_count / fps
        cap.release()

        if duration > MAX_VIDEO_DURATION_SEC:
            os.remove(filepath)  # Delete the uploaded file
            return jsonify({
                'success': False,
                'error': f'Video çok uzun! Max {MAX_VIDEO_DURATION_SEC} saniye, yüklenen: {duration:.0f} saniye'
            })

    # Initialize analysis state
    video_analyses[video_id] = {
        'status': 'processing',
        'progress': 0,
        'filepath': filepath,
        'exercise_type': exercise_type,
        'reps': 0,
        'form_score': 100,
        'avg_form_score': 100,
        'grade': 'A',
        'state': 'READY',
        'feedback': '',
        'engine': ExerciseEngine(),
        'total_frames': 0,
        'processed_frames': 0
    }

    # Load exercise into engine (not used in subprocess mode, but keep for status)
    video_analyses[video_id]['engine'].set_exercise(exercise_type)

    # Start background processing using subprocess
    thread = threading.Thread(target=process_video_subprocess, args=(video_id,))
    thread.daemon = True
    thread.start()

    return jsonify({
        'success': True,
        'video_id': video_id,
        'message': 'Video uploaded, processing started'
    })

def process_video_subprocess(video_id):
    """Process video in a separate subprocess to avoid memory issues"""
    import subprocess
    import json

    logger.info(f"Starting video processing (subprocess) for {video_id}")

    analysis = video_analyses.get(video_id)
    if not analysis:
        logger.error(f"Analysis not found for {video_id}")
        return

    analysis['status'] = 'processing'

    # Output paths
    output_json_path = os.path.join(UPLOAD_FOLDER, f"{video_id}_results.json")
    output_video_path = os.path.join(UPLOAD_FOLDER, f"{video_id}_processed.mp4")

"""TRA body-shape rules for Phase 3 label generation."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass
from typing import Any

from trampoline.features import summarize_jump_feature_rows
from trampoline.schema import BodyShapeLabel, JumpLabelRecord, JumpSegment, LabelsArtifact


TRA_V1_EXCLUSIONS = [
    "D-score",
    "ToF",
    "SYN",
    "TUM",
    "DMT",
]


DIFFICULTY_ORDER: dict[BodyShapeLabel, int] = {
    "tuck": 0,
    "pike": 1,
    "straight": 2,
}


@dataclass(frozen=True)
class ShapeClassifierConfig:
    """Thresholds for the simplified TRA body-shape classifier."""

    tuck_trunk_max: float = 90.0
    tuck_knee_max: float = 135.0
    pike_trunk_max: float = 130.0
    pike_knee_min: float = 140.0
    straight_trunk_min: float = 145.0
    straight_knee_min: float = 150.0
    min_confidence: float = 0.30


def _canonical_scores(trunk_thigh_angle: float, thigh_shank_angle: float) -> dict[BodyShapeLabel, float]:
    """Return soft similarity scores used for ambiguous frames."""

    canonical_targets: dict[BodyShapeLabel, tuple[float, float]] = {
        "tuck": (70.0, 85.0),
        "pike": (92.0, 160.0),
        "straight": (165.0, 170.0),
    }
    scores: dict[BodyShapeLabel, float] = {}
    for label, (target_trunk, target_knee) in canonical_targets.items():
        distance = abs(trunk_thigh_angle - target_trunk) + abs(thigh_shank_angle - target_knee)
        scores[label] = 1.0 / (1.0 + distance)
    return scores


def classify_frame_shape(
    trunk_thigh_angle: float | None,
    thigh_shank_angle: float | None,
    *,
    config: ShapeClassifierConfig | None = None,
) -> tuple[BodyShapeLabel | None, float]:
    """Classify a single frame into tuck, pike, or straight."""

    if trunk_thigh_angle is None or thigh_shank_angle is None:
        return None, 0.0

    thresholds = config or ShapeClassifierConfig()
    if trunk_thigh_angle <= thresholds.tuck_trunk_max and thigh_shank_angle <= thresholds.tuck_knee_max:
        margin = min(
            (thresholds.tuck_trunk_max - trunk_thigh_angle) / thresholds.tuck_trunk_max,
            (thresholds.tuck_knee_max - thigh_shank_angle) / thresholds.tuck_knee_max,
        )
        return "tuck", max(0.0, min(1.0, 0.65 + margin))

    if trunk_thigh_angle <= thresholds.pike_trunk_max and thigh_shank_angle >= thresholds.pike_knee_min:
        margin = min(
            (thresholds.pike_trunk_max - trunk_thigh_angle) / thresholds.pike_trunk_max,
            (thigh_shank_angle - thresholds.pike_knee_min) / max(1.0, 180.0 - thresholds.pike_knee_min),
        )
        return "pike", max(0.0, min(1.0, 0.60 + margin))

    if trunk_thigh_angle >= thresholds.straight_trunk_min and thigh_shank_angle >= thresholds.straight_knee_min:
        margin = min(
            (trunk_thigh_angle - thresholds.straight_trunk_min) / max(1.0, 180.0 - thresholds.straight_trunk_min),
            (thigh_shank_angle - thresholds.straight_knee_min) / max(1.0, 180.0 - thresholds.straight_knee_min),
        )
        return "straight", max(0.0, min(1.0, 0.60 + margin))

    canonical_scores = _canonical_scores(trunk_thigh_angle, thigh_shank_angle)
    best_label = max(canonical_scores, key=canonical_scores.get)
    return best_label, min(0.55, round(canonical_scores[best_label] * 10.0, 3))


def _resolved_label(frame_labels: list[BodyShapeLabel]) -> BodyShapeLabel:
    return min(frame_labels, key=lambda label: (DIFFICULTY_ORDER[label], label))


def classify_jump_shape(
    jump_segment: JumpSegment,
    feature_rows: list[dict[str, Any]],
    *,
    override_label: BodyShapeLabel | None = None,
    override_note: str | None = None,
    config: ShapeClassifierConfig | None = None,
) -> JumpLabelRecord:
    """Classify one jump using the mid-flight lowest-difficulty rule."""

    thresholds = config or ShapeClassifierConfig()
    summary = summarize_jump_feature_rows(feature_rows)
    eligible_rows = [
        row
        for row in feature_rows
        if row.get("is_mid_flight_window")
        and row.get("trunk_thigh_angle") is not None
        and row.get("thigh_shank_angle") is not None
    ]
    fallback_reason = None
    if not eligible_rows:
        eligible_rows = [
            row
            for row in feature_rows
            if row.get("is_flight_phase")
            and row.get("trunk_thigh_angle") is not None
            and row.get("thigh_shank_angle") is not None
        ]
        fallback_reason = "No valid mid-flight frames above visibility threshold; used the full flight window."

    frame_labels: list[BodyShapeLabel] = []
    frame_confidences: list[float] = []
    for row in eligible_rows:
        frame_label, frame_confidence = classify_frame_shape(
            row.get("trunk_thigh_angle"),
            row.get("thigh_shank_angle"),
            config=thresholds,
        )
        if frame_label is None:
            continue
        frame_labels.append(frame_label)
        frame_confidences.append(frame_confidence)

    if not frame_labels:
        frame_labels = ["straight"]
        frame_confidences = [thresholds.min_confidence]
        if fallback_reason:
            fallback_reason = (
                f"{fallback_reason} No valid angle pair remained, so the classifier defaulted to straight."
            )
        else:
            fallback_reason = "No valid mid-flight angle pair was available, so the classifier defaulted to straight."

    counts = Counter(frame_labels)
    auto_label = _resolved_label(frame_labels)
    share = counts[auto_label] / len(frame_labels)
    visibility_values = [float(row.get("visibility_score") or 0.0) for row in eligible_rows] or [0.0]
    confidence = min(
        0.99,
        max(
            thresholds.min_confidence,
            0.35 + (0.40 * share) + (0.15 * (sum(frame_confidences) / len(frame_confidences))) + (0.10 * (sum(visibility_values) / len(visibility_values))),
        ),
    )
    if fallback_reason:
        confidence = min(confidence, 0.58)

    decision_reason = (
        "mid-flight lowest-difficulty rule: "
        f"tuck={counts.get('tuck', 0)}, pike={counts.get('pike', 0)}, straight={counts.get('straight', 0)}; "
        f"resolved to {auto_label}."
    )
    resolved_label = override_label or auto_label
    if override_label:
        decision_reason = f"{decision_reason} Manual override applied as {override_label}."

    return JumpLabelRecord(
        jump_id=jump_segment.jump_id,
        sequence_index=jump_segment.sequence_index,
        auto_label=auto_label,
        resolved_label=resolved_label,
        override_label=override_label,
        override_note=override_note,
        confidence=round(confidence, 3),
        source="rules_tra_v1",
        decision_reason=decision_reason,
        fallback_reason=fallback_reason,
        feature_summary=summary,
    )


def classify_labels_artifact(
    *,
    analysis_id: str,
    jump_segments: list[JumpSegment],
    feature_rows: list[dict[str, Any]],
    override_map: dict[str, tuple[BodyShapeLabel | None, str | None]] | None = None,
    config: ShapeClassifierConfig | None = None,
) -> LabelsArtifact:
    """Classify every jump in one analysis into the Phase 3 label artifact."""

    override_map = override_map or {}
    rows_by_jump_id: dict[str, list[dict[str, Any]]] = {}
    for row in feature_rows:
        rows_by_jump_id.setdefault(str(row["jump_id"]), []).append(row)

    labels = []
    for jump_segment in jump_segments:
        override_label, override_note = override_map.get(jump_segment.jump_id, (None, None))
        labels.append(
            classify_jump_shape(
                jump_segment,
                rows_by_jump_id.get(jump_segment.jump_id, []),
                override_label=override_label,
                override_note=override_note,
                config=config,
            )
        )

    return LabelsArtifact(analysis_id=analysis_id, labels=labels)

